 // ---- Priority and legal responses ----
 // Shared clients offer actions only for their assigned seat. Hotseat can switch
 // control to the responding player without changing the active turn.
 function responseActions(owner){
  const g=getGame(),section=el('div',undefined,'play-response-actions'),player=g.players[owner];
  section.setAttribute('aria-label','Your response options');
  const spells=el('div',undefined,'play-response-options');
  for(const zone of ['hand','command','graveyard','exile'])for(const card of player.zones[zone]){
   if(card.hidden||card.faceDown||!castingPermission(g,owner,card,zone)||/\bLand\b/.test(cardFace(card).type_line||'')||castingTiming(g,owner,card)||!spellHasLegalChoices(g,owner,card))continue;
   const affordable=manaPreview(owner).has(card.instance),action=button(cardFace(card).name+' '+(cardFace(card).mana_cost||''),()=>openCast(card.instance),'play-response-option');
   action.dataset.responseCard=card.instance;action.disabled=!affordable;action.title=affordable?'Cast in response':"Not enough available mana.";spells.append(action);
  }
  for(const card of player.zones.battlefield)if(card.manifested&&card.faceDown){const action=button('Turn face up: '+card.name,()=>dispatch({type:'turnFaceUp',id:card.instance}),'play-response-option');action.disabled=!!manifestFaceUpError(g,owner,card);action.dataset.turnFaceUp=card.instance;spells.append(action);}
  if(spells.children.length)section.append(el('strong','Spells'),spells);
  const sources=el('div',undefined,'play-response-options');
  for(const zone of ['battlefield','hand'])for(const card of player.zones[zone]){
   if(card.hidden||card.faceDown)continue;
   const abilities=activatedAbilities(g,owner,card).filter(a=>zone==='hand'?a.cycling||a.handOnly:!a.cycling&&!a.handOnly).filter(a=>{const error=activationError(g,owner,card,a);return !error||error==='Not enough eligible floating mana.';});
   if(abilities.length){const action=button(card.name+' - abilities',()=>openSource(card.instance),'play-response-option');action.dataset.responseSource=card.instance;sources.append(action);}
   if(zone==='battlefield'&&!loyaltyStatus(g,owner,card).reason)for(const ability of availableLoyaltyAbilities(g,owner,card)){
    if(!ability.variable&&ability.delta<0&&(card.counters?.loyalty||0)<-ability.delta)continue;
    const action=button(card.name+' '+ability.label+': '+ability.text,()=>useLoyaltyAbility(card.instance,ability.key),'play-response-option');action.dataset.responseLoyalty=card.instance;sources.append(action);
   }
  }
  if(sources.children.length)section.append(el('strong','Mana and abilities'),sources);
  if(!spells.children.length&&!sources.children.length)section.append(hint('Use Pass when you are ready to continue.'));
  else section.append(hint('Add mana here or from the table, then choose a response. Gray spells need more eligible mana than your pool and available sources provide.'));
  return section;
 }
